from html import escape
from pathlib import Path

sections = [
('01-profile','โปรไฟล์และการแสดงหน้าร้าน','เข้าเมนูโปรไฟล์ร้านเพื่อแก้ชื่อ รูป คำอธิบาย และช่องทางติดต่อ จากนั้นตรวจการแสดงผลด้วยปุ่มเปิดหน้าร้านลูกค้า','การปิดหน้าร้านหยุดการเข้าหน้าร้าน รับคิว และออเดอร์ใหม่ตามเงื่อนไขระบบ ออเดอร์เดิมยังติดตามได้'),
('02-products','แคตตาล็อกสินค้า','เปิดเมนูแคตตาล็อกเพื่อดูสินค้าของร้าน ค้นหา กรอง เลือกมุมมอง และเพิ่มสินค้าหรือสร้างชุดสินค้า','การสร้างสินค้าในคลังกับการจัดสรรสินค้าให้ช่องทางขายเป็นคนละขั้นตอน'),
('03-product-form','เพิ่มสินค้าใหม่','กดเพิ่มสินค้า กรอกชื่อ หมวดหมู่ ราคา รูป และรายละเอียดของแต่ละรายการ เลือกการนับสต็อกแล้วบันทึก','หากมีหลายตัวเลือก ตรวจชื่อและราคาของแต่ละตัวเลือกก่อนเปิดขาย'),
('04-events','สร้างและเลือกอีเวนต์','เปิดเมนูอีเวนต์เพื่อดูงานของร้าน กดเพิ่มอีเวนต์สำหรับงานใหม่ หรือกดจัดการเพื่อเข้าไปตั้งค่างานเดิม','ตรวจวันและสถานะงานให้ตรงก่อนนำลิงก์ไปแชร์'),
('05-event-form','รายละเอียดอีเวนต์','กรอกชื่องาน วันเริ่มและวันสิ้นสุด เขตเวลา สถานที่ และรายละเอียดบูธ แล้วบันทึก','เวลาจัดงานและเขตเวลามีผลต่อช่วงขายและการเปิดบริการ'),
('06-workspace','หน้าเตรียมงาน','หน้าเตรียมงานรวมทางลัดไปยังสินค้า ช่วงขาย โปรโมชั่น ออเดอร์ คิว และรายงานของอีเวนต์ที่เลือก','ใช้รายการตรวจความพร้อมเพื่อดูสิ่งที่ยังต้องตั้งค่าก่อนเริ่มขาย'),
('07-event-catalog','สินค้าและสต็อกในอีเวนต์','เลือกสินค้าที่จะขายในงาน ตรวจราคา สถานะ และสต็อกที่จัดสรร จากนั้นบันทึกการเปลี่ยนแปลง','สินค้าที่ซ่อนยังกันสต็อกไว้ หากต้องการคืนส่วนที่ไม่ได้ใช้ให้ลดจำนวนจัดสรร สต็อกอีเวนต์แยกจากแคมเปญออนไลน์'),
('08-order-settings','ช่วงขายและรับเงิน','เปิดหน้าช่วงขายและรับเงิน เลือกช่วงก่อนงาน วันงาน หรือหลังงาน ตั้งเวลาขายและวิธีรับชำระตามที่ต้องการ','ช่วงขายที่สิ้นสุดแล้วเปิดใหม่ไม่ได้ หลังงานจบขยายเวลาปิดได้เฉพาะช่วงขายหลังงานที่ยังเปิดอยู่'),
('09-pos-queue','จัดการคิวจากหน้า POS','หากดูแลร้านและคิวเอง ให้เปิดหน้า POS ของอีเวนต์ แล้วกดปุ่ม “จัดการคิว” เพื่อดูคิวที่รอ เรียกคิว และจัดการสถานะ จากนั้นปิดแผงเพื่อกลับมาขายต่อในหน้าเดิม','หากมีทีมงานคิวแยก สามารถใช้หน้าจัดการคิวแบบเต็มสำหรับติดตามและดูแลคิวโดยเฉพาะ'),
('10-pos','ขายหน้าบูธด้วย POS','เลือกสินค้าลงตะกร้า ตรวจจำนวน ยอดรวม และโปรโมชั่น แล้วเข้าสู่ขั้นตอนรับชำระ','ตรวจเงินที่ได้รับจริงก่อนบันทึกการชำระ การคืนเงินไม่ใช่การคืนสต็อกอัตโนมัติ'),
('11-promotions','โปรโมชั่นของร้าน','เปิดเมนูโปรโมชั่นเพื่อสร้างและจัดการข้อเสนอของร้าน โปรโมชั่นที่สร้างสามารถเลือกใช้กับช่องทางและช่วงขายที่ต้องการ','ภาพเป็นร้านตัวอย่างที่ยังไม่มีโปรโมชั่น'),
('12-promotion-editor','สร้างโปรโมชั่น','กดสร้างโปรโมชั่น ตั้งชื่อ เลือกเงื่อนไขและสิทธิประโยชน์ จากนั้นกำหนดช่องทาง ช่วงเวลา และวิธีใช้ร่วมกับโปรอื่น','ใช้การทดลองโปรเพื่อตรวจเงื่อนไขก่อนบันทึก โดยการขายจริงยังตรวจสต็อกและโควตา'),
('13-gift-settings','กำหนดของแถม','เปิดสิทธิประโยชน์ของแถม เลือกสินค้าและจำนวนต่อสิทธิ์ หากต้องการแถมรวมไม่เกิน 1 ชิ้นต่อออเดอร์ให้ใส่ 1 ในช่องจำกัดของแถมต่อออเดอร์','โควตาของแถมรวมทุกช่องทางเป็นอีกช่องหนึ่ง แยกจากเพดานต่อออเดอร์'),
('14-event-promotions','เลือกโปรโมชั่นในอีเวนต์','ในอีเวนต์เปิดแท็บโปรโมชั่น เลือกโปรของร้านและกำหนดช่วงก่อนงาน วันงาน หรือหลังงาน รวมถึงกติกาการใช้ร่วมกัน','หากโปรชนกัน หน้าต่างยืนยันจะแยกช่วงและชื่อโปรที่เกี่ยวข้องให้อ่านก่อนยืนยัน'),
('15-preorders','ออเดอร์ก่อนงาน','ดูรายการตามสถานะ ค้นด้วยข้อมูลที่เกี่ยวข้อง แล้วเปิดสลิปเพื่อตรวจยอดก่อนยืนยันหรือปฏิเสธ','ระบบกันสต็อกเพื่อชำระเงิน 15 นาที ร้านต้องตรวจเงินที่ได้รับจริงก่อนยืนยัน ภาพนี้เป็นข้อมูลจำลองจึงไม่มีออเดอร์'),
('16-postorders','ออเดอร์หลังงาน','เปิดหน้าออเดอร์หลังงานเพื่อตรวจสลิปและติดตามรายการส่งสินค้า ใช้ตัวกรองและค้นหารายการที่ต้องการ','ยอดและสินค้าที่ต้องเตรียมแยกจากหน้าออเดอร์ก่อนงาน'),
('17-pickup','รับสินค้า','เปิดแท็บรับสินค้า ค้นด้วยรหัส ตรวจเลขลำดับ ชื่อผู้รับ และสินค้าแต่ละรายการ แล้วกดยืนยันเมื่อส่งมอบครบจริง','หากระบบแจ้งว่าสินค้ารับสั่งผลิตยังไม่ครบ ให้รับสินค้าเข้าสต็อกก่อนส่งมอบ แล้วลองยืนยันใหม่ ภาพนี้ไม่มีออเดอร์ตัวอย่าง'),
('18-online','สร้างแคมเปญออนไลน์','เปิดเมนูขายออนไลน์ ตั้งชื่อและช่วงเปิดปิด เลือกการจัดส่งหรือรับเอง แล้วสร้างแคมเปญ','การขายออนไลน์เป็นช่องทางแยกจากอีเวนต์ ตรวจสต็อกและการตั้งค่าของช่องทางนี้โดยเฉพาะ'),
('19-campaign','เตรียมแคมเปญ','เปิดแคมเปญเพื่อตรวจความพร้อม สินค้า โปรโมชั่น คำสั่งซื้อ และการตั้งค่า แล้วตรวจหน้าร้านก่อนเผยแพร่','ค่าที่เห็นในภาพเป็นข้อมูลร้านจำลอง'),
('20-campaign-settings','จุดรับสินค้าและช่องทางชำระเงิน','ในแท็บตั้งค่า เพิ่มหรือแก้ไขจุดรับและช่องทางชำระเงิน ตรวจวันและเวลานัดรับก่อนบันทึก ออเดอร์เดิมเก็บรายละเอียดจุดรับเดิมไว้ หากนัดเปลี่ยนให้ติดต่อผู้ซื้อ','เวลาเริ่มขายแก้ได้ก่อนเริ่มเท่านั้น ช่วงขายที่สิ้นสุดแล้วเปิดใหม่ไม่ได้ หากลดช่วงขาย ระบบจะขอให้ยืนยัน'),
('21-team','ทีมและสิทธิ์','เชิญทีมด้วยอีเมล เลือกบทบาทและอีเวนต์ที่ให้เข้าถึง แล้วส่งคำเชิญ','ให้สิทธิ์ตามหน้าที่ ตรวจขอบเขตการเข้าถึงก่อนส่ง'),
('22-reports','รายงานยอดขาย','เปิดแท็บยอดขายของงาน เลือกช่วงวันที่และตรวจตัวเลขกับออเดอร์ที่เกี่ยวข้อง','อ่านความหมายของยอดและช่วงเวลาให้ตรงก่อนนำไปสรุป'),
('23-history','ประวัติการขาย','เปิดแท็บประวัติ เลือกช่วงวันที่ ค้นหา และกรองรายการเพื่อทบทวนการขาย','ตรวจสถานะออเดอร์ การชำระเงิน และการคืนเงินแยกกัน'),
('24-problems','ปัญหาออเดอร์','เปิดเมนูปัญหาออเดอร์เพื่อดูรายการที่ต้องติดตามและตรวจข้อมูลจากลูกค้า','ขอข้อมูลเท่าที่จำเป็น ไม่ขอรหัสผ่านหรือ OTP และหลีกเลี่ยงเผยแพร่ข้อมูลลูกค้า'),
]
out=Path('docs/manuals');out.mkdir(parents=True,exist_ok=True)
css='''@page{size:A4;margin:0}*{box-sizing:border-box}body{margin:0;color:#18304d;font-family:"Noto Sans Thai","Thonburi","Tahoma",sans-serif}.page{width:210mm;height:297mm;padding:16mm 17mm;break-after:page;position:relative}.page:last-child{break-after:auto}header{border-bottom:1px solid #d4e3ed;padding-bottom:9px;color:#2e6d9b;font-size:11px;font-weight:bold;display:flex;justify-content:space-between}header span{color:#8196a7;font-weight:normal}h1{font-size:25px;line-height:1.35;margin:18px 0 8px}h2{font-size:15px;margin:12px 0 5px}p{font-size:13px;line-height:1.7;margin:7px 0}.lead{font-size:15px;color:#536d82}.figure{margin:12px 0 8px;border:1px solid #dce7ef;border-radius:8px;overflow:hidden;background:#f3f7fa}.figure img{display:block;width:100%;height:auto;max-height:130mm;object-fit:contain}.caption{font-size:10px;color:#71899a}.tip{background:#edf6fc;border-left:3px solid #2f76ab;padding:10px 13px;margin-top:12px;font-size:12px;line-height:1.6}footer{position:absolute;bottom:12mm;left:17mm;right:17mm;border-top:1px solid #dce7ef;padding-top:6px;font-size:10px;color:#8196a7}.toc{columns:2;column-gap:20px;font-size:12px;line-height:2.15;list-style:none;padding:0}.toc li{break-inside:avoid}.cover{background:#f2f8fc}.badge{color:#2e6d9b;font-size:12px;font-weight:bold;letter-spacing:.08em}.cover h1{font-size:34px;margin-top:65px}.intro{padding:17px;background:white;border-radius:12px;margin-top:24px}'''
pages=['<!doctype html><html lang="th"><head><meta charset="utf-8"><title>คู่มือใช้งาน Paimon สำหรับร้านค้า</title><style>'+css+'</style></head><body>']
pages.append('<section class="page cover"><header>✦ PAIMON <span>คู่มือร้านค้าและทีมงาน</span></header><p class="badge">ฉบับภาพหน้าจอปัจจุบัน · 15 พฤศจิกายน 2569</p><h1>คู่มือใช้งาน<br>สำหรับร้านค้า</h1><p class="lead">ตั้งร้าน เตรียมอีเวนต์ ขายหน้าบูธ และจัดการออเดอร์</p><div class="intro"><h2>เริ่มจากสิ่งที่ร้านต้องการ</h2><p>ขายหน้าบูธ: แคตตาล็อก → อีเวนต์ → สินค้าและสต็อก → POS<br>ขายล่วงหน้าหรือออนไลน์: ตั้งช่วงขาย วิธีรับเงิน และการส่งมอบ<br>ใช้คิว: เปิด POS แล้วกดจัดการคิวเพื่อเรียกคิวระหว่างขาย</p></div><div class="tip">ภาพทั้งหมดถ่ายจากระบบทดสอบโดยใช้ร้านและข้อมูลจำลอง ไม่มีข้อมูลลูกค้าจริง บางหน้าจึงแสดงรายการว่าง</div><footer>PAIMON GUIDE · ฉบับภาพอัปเดต</footer></section>')
toc=''.join(f'<li>{i+1:02d} · {escape(title)} <span> {i+3}</span></li>' for i,(_,title,*_) in enumerate(sections))
pages.append('<section class="page"><header>✦ PAIMON <span>สารบัญ</span></header><h1>เลือกเรื่องที่ต้องการ</h1><p class="lead">ภาพแต่ละหน้ามาจากระบบรุ่นปัจจุบัน รายละเอียดอาจเปลี่ยนเมื่อมีการอัปเดต</p><ol class="toc">'+toc+'</ol><div class="tip">ภาพจากร้านจำลองบนระบบทดสอบ ข้อมูลและชื่อทั้งหมดใช้เพื่อประกอบคู่มือ</div><footer>สารบัญ · 2</footer></section>')
for i,(img,title,body,tip) in enumerate(sections):
 pages.append(f'<section class="page"><header>✦ PAIMON <span>คู่มือร้านค้า · {i+1:02d}</span></header><h1>{escape(title)}</h1><div class="figure"><img src="screenshots/{img}.png" alt="หน้าจอ {escape(title)} จากร้านจำลอง"></div><p class="caption">ภาพหน้าจอจากระบบทดสอบ · ร้านและข้อมูลจำลอง</p><h2>วิธีใช้</h2><p>{escape(body)}</p><div class="tip"><b>ควรรู้:</b> {escape(tip)}</div><footer>PAIMON GUIDE · {i+3}</footer></section>')
pages.append('</body></html>');(out/'paimon-user-manual.html').write_text(''.join(pages),encoding='utf8');print('sections',len(sections),'html created')
